begin;
grant insert,select on pg_temp.test_assertions to sivirinia_worker;
insert into auth.users(id,email,email_confirmed_at) values('91000000-0000-0000-0000-000000000001','ocr-owner@example.test',now()),('91000000-0000-0000-0000-000000000002','ocr-other@example.test',now());
insert into public.organizations(id,name) values('92000000-0000-0000-0000-000000000001','OCR teste');
insert into public.organization_members(organization_id,user_id,role) values('92000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001','owner');
set local role authenticated;
select set_config('request.jwt.claim.sub','91000000-0000-0000-0000-000000000001',true);
select pg_temp.assert_throws($$select public.enqueue_document_with_ocr('92000000-0000-0000-0000-000000000001','OCR inválido','faq.txt','text','eA==',true)$$,'P0001','Documento não suporta OCR','OCR exige arquivo raster/PDF/DOCX, não texto manual');
select set_config('test.task',public.enqueue_document_with_ocr('92000000-0000-0000-0000-000000000001','Digitalizado','scan.pdf','file','eA==',true)::text,true);
select pg_temp.assert_eq((select ocr_requested from public.document_tasks where id=current_setting('test.task')::uuid),true,'Opt-in de OCR é persistido na tarefa');
select set_config('request.jwt.claim.sub','91000000-0000-0000-0000-000000000002',true);
select pg_temp.assert_eq((select count(*)::int from public.document_tasks),0,'Metadados de OCR não atravessam tenant');
select pg_temp.assert_throws($$select public.enqueue_document_with_ocr('92000000-0000-0000-0000-000000000001','Invasão','scan.pdf','file','eQ==',true)$$,'P0001','Sem permissão','Wrapper OCR não ignora autorização');
reset role;
set local role sivirinia_worker;
select set_config('test.claim',sivirinia_internal.claim_document()::text,true);
select pg_temp.assert_eq((current_setting('test.claim')::jsonb->>'ocr')::boolean,true,'Worker recebe explicitamente a opção OCR');
select sivirinia_internal.fail_document(current_setting('test.task')::uuid,(current_setting('test.claim')::jsonb->>'token')::uuid,'ocr_page_limit',false);
reset role;
select pg_temp.assert_eq((select error_code from public.document_tasks where id=current_setting('test.task')::uuid),'ocr_page_limit','Erro de limite OCR permanece identificável');
select pg_temp.assert_eq((select status from public.document_tasks where id=current_setting('test.task')::uuid),'failed','Limite OCR não causa retries sem utilidade');
set local role anon;
select pg_temp.assert_throws($$select public.enqueue_document_with_ocr('92000000-0000-0000-0000-000000000001','Anon','scan.pdf','file','eQ==',true)$$,'42501',null,'Anônimo não enfileira OCR');
reset role;
select 'ASSERTIONS='||count(*) from pg_temp.test_assertions;
rollback;
